values
  ('ae626e1b-1179-46eb-b2a0-f8dcb24fb397', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Experimental foundations', 'This module establishes experimental foundations as the course''s first working framework. It supplies the language and representations needed before the path advances to wavefunctions and probability.', 0),
  ('9c3ed5f0-bac3-4bbf-880d-a375e4ca7996', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'ae626e1b-1179-46eb-b2a0-f8dcb24fb397', 'subtopic'::public.curated_course_node_type, 'Photons', 'Photons identifies a specific object, distinction, or relationship within experimental foundations. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before matter waves because that next topic assumes this starting point.', 0),
  ('2d54c108-97b6-430c-bb66-0e9d546a3c7d', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'ae626e1b-1179-46eb-b2a0-f8dcb24fb397', 'subtopic'::public.curated_course_node_type, 'Matter waves', 'Matter waves identifies a specific object, distinction, or relationship within experimental foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After photons, matter waves supplies what is needed to address interference.', 1),
  ('25a558c5-f80c-4036-a5d1-9e92aabf931d', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'ae626e1b-1179-46eb-b2a0-f8dcb24fb397', 'subtopic'::public.curated_course_node_type, 'Interference', 'Interference identifies a specific object, distinction, or relationship within experimental foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After matter waves, interference supplies what is needed to address stern–gerlach.', 2),
  ('31316d8a-aeac-44b2-be1e-4dafe42d8683', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'ae626e1b-1179-46eb-b2a0-f8dcb24fb397', 'subtopic'::public.curated_course_node_type, 'Stern–Gerlach', 'Stern–Gerlach identifies a specific object, distinction, or relationship within experimental foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After interference, stern–gerlach supplies what is needed to address scale.', 3),
  ('c6aba6f8-452f-453a-99d4-8931266e5436', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'ae626e1b-1179-46eb-b2a0-f8dcb24fb397', 'subtopic'::public.curated_course_node_type, 'Scale', 'Scale identifies a specific object, distinction, or relationship within experimental foundations. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, scale carries the completed idea into wavefunctions and probability.', 4),
  ('81f2b6ab-a956-4601-81ab-fc9d25506a6e', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Wavefunctions and probability', 'This module builds directly on experimental foundations and develops wavefunctions and probability. It belongs here because its methods and distinctions are prerequisites for schrödinger dynamics.', 1),
  ('29efccb5-c5fe-4ec4-9133-ded71e38e11d', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '81f2b6ab-a956-4601-81ab-fc9d25506a6e', 'subtopic'::public.curated_course_node_type, 'Normalization', 'Normalization identifies a specific object, distinction, or relationship within wavefunctions and probability. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before current because that next topic assumes this starting point.', 0),
  ('3124db89-cb53-4785-a1ae-ac2633dd32d3', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '81f2b6ab-a956-4601-81ab-fc9d25506a6e', 'subtopic'::public.curated_course_node_type, 'Current', 'Current identifies a specific object, distinction, or relationship within wavefunctions and probability. Learners need to recognize and use it before combining this module''s ideas in later work. After normalization, current supplies what is needed to address superposition.', 1),
  ('e944bb69-b8a0-4ad2-87da-5b7537edb1b2', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '81f2b6ab-a956-4601-81ab-fc9d25506a6e', 'subtopic'::public.curated_course_node_type, 'Superposition', 'Superposition identifies a specific object, distinction, or relationship within wavefunctions and probability. Learners need to recognize and use it before combining this module''s ideas in later work. After current, superposition supplies what is needed to address boundary conditions.', 2),
  ('cfbbdd77-bc88-4b17-b6d8-5e7a0edd634c', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '81f2b6ab-a956-4601-81ab-fc9d25506a6e', 'subtopic'::public.curated_course_node_type, 'Boundary conditions', 'Boundary conditions identifies a specific object, distinction, or relationship within wavefunctions and probability. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, boundary conditions carries the completed idea into schrödinger dynamics.', 3),
  ('524b955e-5957-4e76-95ed-06af0edb586b', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Schrödinger dynamics', 'This module builds directly on wavefunctions and probability and develops schrödinger dynamics. It belongs here because its methods and distinctions are prerequisites for operators and measurement.', 2),
  ('3808682c-d158-42a3-89b5-c99d7b5e841c', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '524b955e-5957-4e76-95ed-06af0edb586b', 'subtopic'::public.curated_course_node_type, 'Time-dependent/independent equations', 'Time-dependent/independent equations identifies a specific object, distinction, or relationship within schrödinger dynamics. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before stationary states because that next topic assumes this starting point.', 0),
  ('8cba8773-3041-4e67-8eef-f183ff546f14', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '524b955e-5957-4e76-95ed-06af0edb586b', 'subtopic'::public.curated_course_node_type, 'Stationary states', 'Stationary states identifies a specific object, distinction, or relationship within schrödinger dynamics. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, stationary states carries the completed idea into operators and measurement.', 1),
  ('256c05ff-3474-4cb8-b08c-07ef20847baf', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Operators and measurement', 'This module builds directly on schrödinger dynamics and develops operators and measurement. It belongs here because its methods and distinctions are prerequisites for one-dimensional wells.', 3),
  ('4197ac76-2cb5-43bc-b536-3bd28ff231c1', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '256c05ff-3474-4cb8-b08c-07ef20847baf', 'subtopic'::public.curated_course_node_type, 'Observables', 'Observables identifies a specific object, distinction, or relationship within operators and measurement. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before eigenstates because that next topic assumes this starting point.', 0),
  ('24bad7f3-14b6-4aac-a422-65e874cca35c', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '256c05ff-3474-4cb8-b08c-07ef20847baf', 'subtopic'::public.curated_course_node_type, 'Eigenstates', 'Eigenstates identifies a specific object, distinction, or relationship within operators and measurement. Learners need to recognize and use it before combining this module''s ideas in later work. After observables, eigenstates supplies what is needed to address expectation.', 1),
  ('c55cfcef-d307-4521-b4dd-89dcc608b69e', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '256c05ff-3474-4cb8-b08c-07ef20847baf', 'subtopic'::public.curated_course_node_type, 'Expectation', 'Expectation identifies a specific object, distinction, or relationship within operators and measurement. Learners need to recognize and use it before combining this module''s ideas in later work. After eigenstates, expectation supplies what is needed to address commutators.', 2),
  ('dea2887c-f2eb-4574-bd28-dc6bc46754b4', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '256c05ff-3474-4cb8-b08c-07ef20847baf', 'subtopic'::public.curated_course_node_type, 'Commutators', 'Commutators identifies a specific object, distinction, or relationship within operators and measurement. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, commutators carries the completed idea into one-dimensional wells.', 3),
  ('55829397-3766-46e4-b4cc-0714c26e32ea', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'One-dimensional wells', 'This module builds directly on operators and measurement and develops one-dimensional wells. It belongs here because its methods and distinctions are prerequisites for barriers and tunneling.', 4),
  ('00e76ca2-5e5b-454f-bd77-38c603f514bb', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '55829397-3766-46e4-b4cc-0714c26e32ea', 'subtopic'::public.curated_course_node_type, 'Infinite/finite wells', 'Infinite/finite wells identifies a specific object, distinction, or relationship within one-dimensional wells. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before bound states because that next topic assumes this starting point.', 0),
  ('b4225457-0cc4-42ea-bc6c-c00b1c9e4766', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '55829397-3766-46e4-b4cc-0714c26e32ea', 'subtopic'::public.curated_course_node_type, 'Bound states', 'Bound states identifies a specific object, distinction, or relationship within one-dimensional wells. Learners need to recognize and use it before combining this module''s ideas in later work. After infinite/finite wells, bound states supplies what is needed to address parity.', 1),
  ('d0717814-da14-4e1b-9cc9-c8498956b3a2', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '55829397-3766-46e4-b4cc-0714c26e32ea', 'subtopic'::public.curated_course_node_type, 'Parity', 'Parity identifies a specific object, distinction, or relationship within one-dimensional wells. Learners need to recognize and use it before combining this module''s ideas in later work. After bound states, parity supplies what is needed to address quantization.', 2),
  ('8b2bab9c-22d6-4728-81f2-e13ed1713d7f', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '55829397-3766-46e4-b4cc-0714c26e32ea', 'subtopic'::public.curated_course_node_type, 'Quantization', 'Quantization identifies a specific object, distinction, or relationship within one-dimensional wells. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, quantization carries the completed idea into barriers and tunneling.', 3),
  ('1ac1d872-b378-4304-aeae-6f1dd218238c', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Barriers and tunneling', 'This module builds directly on one-dimensional wells and develops barriers and tunneling. It belongs here because its methods and distinctions are prerequisites for harmonic oscillator.', 5),
  ('bf6f089f-12dc-498f-b0d5-d914bdfeb233', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '1ac1d872-b378-4304-aeae-6f1dd218238c', 'subtopic'::public.curated_course_node_type, 'Scattering states', 'Scattering states identifies a specific object, distinction, or relationship within barriers and tunneling. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before transmission because that next topic assumes this starting point.', 0),
  ('9e5a99ce-bb3b-4537-beda-af526fce48d6', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '1ac1d872-b378-4304-aeae-6f1dd218238c', 'subtopic'::public.curated_course_node_type, 'Transmission', 'Transmission identifies a specific object, distinction, or relationship within barriers and tunneling. Learners need to recognize and use it before combining this module''s ideas in later work. After scattering states, transmission supplies what is needed to address resonances.', 1),
  ('bae36365-6078-47e4-9ca3-1da0d794fbb8', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '1ac1d872-b378-4304-aeae-6f1dd218238c', 'subtopic'::public.curated_course_node_type, 'Resonances', 'Resonances identifies a specific object, distinction, or relationship within barriers and tunneling. Learners need to recognize and use it before combining this module''s ideas in later work. After transmission, resonances supplies what is needed to address applications.', 2),
  ('6a316c0a-e818-4b6a-b12b-6bd979921a1f', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '1ac1d872-b378-4304-aeae-6f1dd218238c', 'subtopic'::public.curated_course_node_type, 'Applications', 'Applications identifies a specific object, distinction, or relationship within barriers and tunneling. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, applications carries the completed idea into harmonic oscillator.', 3),
  ('8ed6ad90-f45e-4012-b362-d721cad62883', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Harmonic oscillator', 'This module builds directly on barriers and tunneling and develops harmonic oscillator. It belongs here because its methods and distinctions are prerequisites for dirac notation and hilbert space.', 6),
  ('19bbe2df-dd73-4e12-ac5c-bcfef2ae83f3', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '8ed6ad90-f45e-4012-b362-d721cad62883', 'subtopic'::public.curated_course_node_type, 'Differential and ladder-operator solutions', 'Differential and ladder-operator solutions identifies a specific object, distinction, or relationship within harmonic oscillator. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before coherent-state glimpse because that next topic assumes this starting point.', 0),
  ('250cb0bc-0d33-43da-aee8-bef3e81044f9', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '8ed6ad90-f45e-4012-b362-d721cad62883', 'subtopic'::public.curated_course_node_type, 'Coherent-state glimpse', 'Coherent-state glimpse identifies a specific object, distinction, or relationship within harmonic oscillator. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, coherent-state glimpse carries the completed idea into dirac notation and hilbert space.', 1),
  ('9d067019-223a-4261-a889-b592546d5aec', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Dirac notation and Hilbert space', 'This module builds directly on harmonic oscillator and develops dirac notation and hilbert space. It belongs here because its methods and distinctions are prerequisites for uncertainty and compatible observables.', 7),
  ('b67d34a6-baa9-49f5-a71a-4b410a958857', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '9d067019-223a-4261-a889-b592546d5aec', 'subtopic'::public.curated_course_node_type, 'Bases', 'Bases identifies a specific object, distinction, or relationship within dirac notation and hilbert space. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before representations because that next topic assumes this starting point.', 0),
  ('f5976ccd-f4d4-4e18-90cc-89b372f2cba3', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '9d067019-223a-4261-a889-b592546d5aec', 'subtopic'::public.curated_course_node_type, 'Representations', 'Representations gives dirac notation and hilbert space a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After bases, representations supplies what is needed to address completeness.', 1),
  ('ea373024-49a0-48b2-b25f-632a8f7bc36e', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '9d067019-223a-4261-a889-b592546d5aec', 'subtopic'::public.curated_course_node_type, 'Completeness', 'Completeness provides a formal guarantee or inference rule for dirac notation and hilbert space, allowing later conclusions to be justified rather than inferred from examples alone. After representations, completeness supplies what is needed to address unitary change.', 2),
  ('651202b1-9066-4726-b61e-4cc5aae235e0', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '9d067019-223a-4261-a889-b592546d5aec', 'subtopic'::public.curated_course_node_type, 'Unitary change', 'Unitary change identifies a specific object, distinction, or relationship within dirac notation and hilbert space. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, unitary change carries the completed idea into uncertainty and compatible observables.', 3),
  ('e0f25697-1ae4-4634-bfce-2a2f9cc7062e', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Uncertainty and compatible observables', 'This module builds directly on dirac notation and hilbert space and develops uncertainty and compatible observables. It belongs here because its methods and distinctions are prerequisites for angular momentum.', 8),
  ('c45c9c59-d220-4ed5-8c64-00f62ca003df', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'e0f25697-1ae4-4634-bfce-2a2f9cc7062e', 'subtopic'::public.curated_course_node_type, 'Robertson relation', 'Robertson relation identifies a specific object, distinction, or relationship within uncertainty and compatible observables. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before wave packets because that next topic assumes this starting point.', 0),
  ('a6809eee-f24d-4857-b4b4-0da95420b7b7', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'e0f25697-1ae4-4634-bfce-2a2f9cc7062e', 'subtopic'::public.curated_course_node_type, 'Wave packets', 'Wave packets identifies a specific object, distinction, or relationship within uncertainty and compatible observables. Learners need to recognize and use it before combining this module''s ideas in later work. After robertson relation, wave packets supplies what is needed to address fourier link.', 1);
