  ('11323e9d-3570-4fac-a0b0-e9296dcb35aa', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '6e79c0c9-f568-4c1b-94b7-d24dd4bf798f', 'subtopic'::public.curated_course_node_type, 'Radial equation', 'Radial equation identifies a specific object, distinction, or relationship within central potentials. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before hydrogen spectrum because that next topic assumes this starting point.', 0),
  ('bc71206e-5c43-40cd-b010-e2567c0b1de1', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '6e79c0c9-f568-4c1b-94b7-d24dd4bf798f', 'subtopic'::public.curated_course_node_type, 'Hydrogen spectrum', 'Hydrogen spectrum identifies a specific object, distinction, or relationship within central potentials. Learners need to recognize and use it before combining this module''s ideas in later work. After radial equation, hydrogen spectrum supplies what is needed to address degeneracy.', 1),
  ('a4174011-adb1-445f-a964-616ae046a29f', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '6e79c0c9-f568-4c1b-94b7-d24dd4bf798f', 'subtopic'::public.curated_course_node_type, 'Degeneracy', 'Degeneracy identifies a specific object, distinction, or relationship within central potentials. Learners need to recognize and use it before combining this module''s ideas in later work. After hydrogen spectrum, degeneracy supplies what is needed to address quantum numbers.', 2),
  ('ad4e9b2b-ca2b-401c-8d52-100a04d817a8', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', '6e79c0c9-f568-4c1b-94b7-d24dd4bf798f', 'subtopic'::public.curated_course_node_type, 'Quantum numbers', 'Quantum numbers identifies a specific object, distinction, or relationship within central potentials. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, quantum numbers carries the completed idea into composite systems.', 3),
  ('b963aefa-0afb-4aaf-9eff-7159f9571e45', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', null, 'topic'::public.curated_course_node_type, 'Composite systems', 'This culminating module draws on central potentials and develops composite systems. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('7a188dbc-3ce1-4dac-bff9-9eb5e184b94d', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'b963aefa-0afb-4aaf-9eff-7159f9571e45', 'subtopic'::public.curated_course_node_type, 'Tensor products', 'Tensor products identifies a specific object, distinction, or relationship within composite systems. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before addition of angular momentum because that next topic assumes this starting point.', 0),
  ('678ef855-e05a-490e-9e1b-74f5e343953f', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'b963aefa-0afb-4aaf-9eff-7159f9571e45', 'subtopic'::public.curated_course_node_type, 'Addition of angular momentum', 'Addition of angular momentum supplies the causal sequence within composite systems, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After tensor products, addition of angular momentum supplies what is needed to address entanglement basics.', 1),
  ('c1fd2783-5aa4-4f5f-8bac-24e14de9a24f', 'ecca54fb-7766-404d-9aa8-378bd965d5e5', 'b963aefa-0afb-4aaf-9eff-7159f9571e45', 'subtopic'::public.curated_course_node_type, 'Entanglement basics', 'Entanglement basics identifies a specific object, distinction, or relationship within composite systems. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, entanglement basics requires ideas from the complete path to be integrated and transferred.', 2);
